import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  CircularProgress,
  MenuItem,
  Select,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';

const authHeaders = () => ({ Authorization: `Bearer ${localStorage.getItem('token')}` });

interface LoanRow {
  _id: string;
  status: string;
  loanAmount?: number;
  loanApplication?: { loanAmount?: number };
  msmeId?: { companyName?: string; carbonScore?: number; industry?: string };
  bankId?: { bankName?: string; contactEmail?: string };
  createdAt?: string;
  reviewDetails?: { reviewComments?: string };
  lendingEvidencePack?: { checklist?: { readinessPercent?: number } } | null;
}

const PartnerLoanReviewPanel: React.FC = () => {
  const [loans, setLoans] = useState<LoanRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState('submitted');
  const [reviewComment, setReviewComment] = useState<Record<string, string>>({});

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await axios.get(buildApiUrl('/partner-account/green-loans'), {
        headers: authHeaders(),
        params: statusFilter ? { status: statusFilter } : {},
      });
      setLoans(res.data?.data?.loans || []);
    } catch (e) {
      setError(axios.isAxiosError(e) ? e.response?.data?.message || e.message : 'Failed to load loans');
      setLoans([]);
    } finally {
      setLoading(false);
    }
  }, [statusFilter]);

  useEffect(() => {
    load();
  }, [load]);

  const updateStatus = async (loanId: string, status: string) => {
    try {
      await axios.put(
        buildApiUrl(`/green-loans/${loanId}/status`),
        { status, reviewComments: reviewComment[loanId] || '' },
        { headers: authHeaders() }
      );
      load();
    } catch (e) {
      setError(axios.isAxiosError(e) ? e.response?.data?.message || e.message : 'Update failed');
    }
  };

  const downloadEvidencePack = async (loanId: string, companyName?: string) => {
    try {
      const res = await axios.get(
        buildApiUrl(`/partner-account/green-loans/${loanId}/evidence-pack`),
        { headers: authHeaders() }
      );
      const pack = res.data?.data?.evidencePack;
      if (!pack) {
        setError('Evidence pack not available');
        return;
      }
      const blob = new Blob([JSON.stringify(pack, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement('a');
      anchor.href = url;
      anchor.download = `green-loan-evidence-${(companyName || loanId).replace(/\s+/g, '-').toLowerCase()}.json`;
      anchor.click();
      URL.revokeObjectURL(url);
    } catch (e) {
      setError(axios.isAxiosError(e) ? e.response?.data?.message || e.message : 'Evidence pack download failed');
    }
  };

  if (loading) {
    return <Box sx={{ py: 4, textAlign: 'center' }}><CircularProgress /></Box>;
  }

  return (
    <Box>
      <Stack direction="row" spacing={2} alignItems="center" sx={{ mb: 2 }}>
        <Typography variant="h6" sx={{ fontWeight: 700 }}>Green loan pipeline</Typography>
        <Select size="small" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}>
          <MenuItem value="">All</MenuItem>
          <MenuItem value="submitted">Submitted</MenuItem>
          <MenuItem value="under_review">Under review</MenuItem>
          <MenuItem value="approved">Approved</MenuItem>
          <MenuItem value="rejected">Rejected</MenuItem>
        </Select>
      </Stack>
      {error ? <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert> : null}
      <TableContainer>
        <Table size="small">
          <TableHead>
            <TableRow>
              <TableCell>Company</TableCell>
              <TableCell>Amount</TableCell>
              <TableCell>Carbon score</TableCell>
              <TableCell>Status</TableCell>
              <TableCell>Evidence</TableCell>
              <TableCell>Review</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {loans.map((loan) => {
              const amount = loan.loanApplication?.loanAmount ?? loan.loanAmount ?? 0;
              const evidencePct = loan.lendingEvidencePack?.checklist?.readinessPercent;
              return (
              <TableRow key={loan._id}>
                <TableCell>{loan.msmeId?.companyName || '—'}</TableCell>
                <TableCell>₹{Number(amount).toLocaleString('en-IN')}</TableCell>
                <TableCell>{loan.msmeId?.carbonScore ?? '—'}</TableCell>
                <TableCell><Chip size="small" label={loan.status} /></TableCell>
                <TableCell>
                  <Stack spacing={0.5}>
                    <Chip
                      size="small"
                      color={evidencePct != null && evidencePct >= 80 ? 'success' : 'default'}
                      label={evidencePct != null ? `${evidencePct}% pack` : 'No pack'}
                    />
                    <Button
                      size="small"
                      disabled={!loan.lendingEvidencePack && evidencePct == null}
                      onClick={() => { void downloadEvidencePack(loan._id, loan.msmeId?.companyName); }}
                    >
                      Download JSON
                    </Button>
                  </Stack>
                </TableCell>
                <TableCell>
                  <Stack spacing={1}>
                    <TextField
                      size="small"
                      placeholder="Review comment"
                      value={reviewComment[loan._id] || ''}
                      onChange={(e) => setReviewComment((p) => ({ ...p, [loan._id]: e.target.value }))}
                    />
                    <Stack direction="row" spacing={0.5}>
                      <Button size="small" onClick={() => updateStatus(loan._id, 'under_review')}>Review</Button>
                      <Button size="small" color="success" onClick={() => updateStatus(loan._id, 'approved')}>Approve</Button>
                      <Button size="small" color="error" onClick={() => updateStatus(loan._id, 'rejected')}>Reject</Button>
                    </Stack>
                  </Stack>
                </TableCell>
              </TableRow>
            );
            })}
            {!loans.length ? (
              <TableRow><TableCell colSpan={6} align="center">No loans in this queue</TableCell></TableRow>
            ) : null}
          </TableBody>
        </Table>
      </TableContainer>
    </Box>
  );
};

export default PartnerLoanReviewPanel;
