import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  CircularProgress,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';

const authHeaders = () => ({ Authorization: `Bearer ${localStorage.getItem('token')}` });

const PartnerGiftReviewPanel: React.FC = () => {
  const [applications, setApplications] = useState<Array<Record<string, unknown>>>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [comments, setComments] = useState<Record<string, string>>({});

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await axios.get(buildApiUrl('/partner-account/gift-applications'), {
        headers: authHeaders(),
        params: { status: 'submitted' },
      });
      setApplications(res.data?.data?.applications || []);
    } catch (e) {
      setError(axios.isAxiosError(e) ? e.response?.data?.message || e.message : 'Failed to load applications');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const updateStatus = async (id: string, status: string) => {
    try {
      await axios.put(
        buildApiUrl(`/gift-applications/${id}/status`),
        { status, reviewComments: comments[id] || '' },
        { headers: authHeaders() }
      );
      load();
    } catch (e) {
      setError(axios.isAxiosError(e) ? e.response?.data?.message || e.message : 'Update failed');
    }
  };

  if (loading) return <CircularProgress />;

  return (
    <Box>
      <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>GIFT scheme review queue</Typography>
      {error ? <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert> : null}
      <TableContainer>
        <Table size="small">
          <TableHead>
            <TableRow>
              <TableCell>Company</TableCell>
              <TableCell>Scheme</TableCell>
              <TableCell>Status</TableCell>
              <TableCell>Actions</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {applications.map((app) => (
              <TableRow key={String(app._id)}>
                <TableCell>{String((app.msmeId as { companyName?: string })?.companyName || '—')}</TableCell>
                <TableCell>{String((app.schemeId as { schemeName?: string })?.schemeName || '—')}</TableCell>
                <TableCell><Chip size="small" label={String(app.status || '—')} /></TableCell>
                <TableCell>
                  <Stack spacing={1}>
                    <TextField
                      size="small"
                      placeholder="Review comment"
                      value={comments[String(app._id)] || ''}
                      onChange={(e) => setComments((p) => ({ ...p, [String(app._id)]: e.target.value }))}
                    />
                    <Stack direction="row" spacing={0.5}>
                      <Button size="small" onClick={() => updateStatus(String(app._id), 'under_review')}>Review</Button>
                      <Button size="small" color="success" onClick={() => updateStatus(String(app._id), 'approved')}>Approve</Button>
                      <Button size="small" color="error" onClick={() => updateStatus(String(app._id), 'rejected')}>Reject</Button>
                    </Stack>
                  </Stack>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>
    </Box>
  );
};

export default PartnerGiftReviewPanel;
